async function connectGemini(value, silent = false) { if (!value) { state.apiKey = null; state.model = null; state.textModel = null; state.modelLimits = { input: 32768, output: 8192 }; setConnectionStatus('idle'); return false; } try { const models = await validateGeminiKey(value); state.model = models.selected; state.textModel = models.selected; state.modelLimits = models.limits; state.availableModels = models.available || []; state.apiKey = value; state.lastRequestStatus = 'idle'; setConnectionStatus('connected', `Ativa · ${state.model}`); return true; } catch (error) { state.apiKey = null; state.model = null; state.textModel = null; state.modelLimits = { input: 32768, output: 8192 }; setConnectionStatus('error', error.message); if (!silent) showQuotaFallback(error.message); return false; } }
