function isTextAttachment(file) { return /^text\//i.test(file.mimeType || file.type) || /^(application\/(json|xml)|text\/(csv|markdown))/i.test(file.mimeType || file.type) || ['txt','md','csv','json','xml','html','htm','css','js','ts','py','svg'].includes(String(file.name || '').split('.').pop().toLowerCase()); }
function mimeMatchesExtension(file) { const ext = String(file.name || '').split('.').pop().toLowerCase(); const mime = String(file.type || '').toLowerCase(); if (!mime) return true; if (['txt','md','csv','html','htm','css','js','ts','py'].includes(ext)) return mime.startsWith('text/') || mime === 'application/javascript' || mime === 'application/json'; if (['json'].includes(ext)) return mime === 'application/json' || mime.startsWith('text/'); if (['xml'].includes(ext)) return mime === 'application/xml' || mime === 'text/xml' || mime.startsWith('text/'); if (ext === 'svg') return mime === 'image/svg+xml' || mime === 'image/svg'; if (ext === 'pdf') return mime === 'application/pdf'; if (['png','jpg','jpeg','gif','webp'].includes(ext)) return mime === `image/${ext === 'jpg' ? 'jpeg' : ext}`; return true; }
