function updateConversationNav() {
  const messages = $('#messages');
  const position = $('#scrollPosition');
  const topButton = $('#scrollTopBtn');
  const bottomButton = $('#scrollBottomBtn');
  if (!messages) return;
  const max = Math.max(0, messages.scrollHeight - messages.clientHeight);
  const ratio = max ? messages.scrollTop / max : 1;
  if (position) position.textContent = ratio < 0.08 ? 'INÍCIO' : ratio > 0.92 ? 'FIM' : `${Math.round(ratio * 100)}%`;
  if (topButton) topButton.disabled = messages.scrollTop <= 8;
  if (bottomButton) bottomButton.disabled = max <= 8 || messages.scrollTop >= max - 8;
  const quick = $('#scrollSettingsBtn');
  if (quick) quick.hidden = messages.scrollTop < 70;
}
function scrollConversation(where) {
  const messages = $('#messages');
  if (!messages) return;
  messages.scrollTo({ top: where === 'top' ? 0 : messages.scrollHeight, behavior: 'smooth' });
  window.setTimeout(updateConversationNav, 420);
}
$('#messages').addEventListener('scroll', updateConversationNav, { passive: true });
$('#scrollTopBtn').addEventListener('click', () => scrollConversation('top'));
$('#scrollBottomBtn').addEventListener('click', () => scrollConversation('bottom'));
$('#scrollSettingsBtn').addEventListener('click', () => { openMenu(); const panel = $('#settingsPanel'); if (panel) { panel.hidden = false; syncSettingsPanel(); } });

